recipe:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
in import (root + "/tests/build/_bazel-cargo-feature-oracles.nix") {
  inherit pkgs;
  pname = "aos-bazel-native-foundation-cargo-baselines";
  packages = ["aos-nix" "aos-transfer" "aos-oci" "aos-systemd-client"];
  variants = {
    default = [];
